    const auto scratch=repo/".cache/contenders/optimization/c3"/("focused-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));fs::create_directories(scratch);auto capped=one();capped["max_closed"]=4;capped["max_frontier"]=100;capped["checkpoint_every"]=1;write_json(scratch/"capped.json",capped);Options opts;opts.mode="c3";opts.repo=repo;opts.input=scratch/"capped.json";opts.out=scratch/"cap-run";opts.iterations=100;check(run_c3(opts)==0,"capped engine run failed");auto report=read_json(opts.out/"report.json");check(report.at("status")==Json("closed_memory_limit")&&!report.at("optimal_within_input_macro_domain").get<bool>(),"capped search claimed exactness");const auto before=read_json(opts.out/"checkpoint.json");check(before.at("state").at("closed_limit").get<bool>(),"cap incompleteness was not checkpointed");opts.resume=true;for(int repeat=0;repeat<3;++repeat){opts.iterations+=100;check(run_c3(opts)==0,"capped resume failed");const auto after=read_json(opts.out/"checkpoint.json");check(after.at("iteration")==before.at("iteration")&&after.at("state")==before.at("state"),"capped resume forgot incompleteness or continued dropped siblings");check(!read_json(opts.out/"report.json").at("optimal_within_input_macro_domain").get<bool>(),"repeated capped resume claimed exactness");}
    auto greedy=read_json(opts.out/"greedy-plan.json");
    check(greedy.at("model_replay").at("valid").get<bool>(),"greedy fallback failed model replay");
    auto incumbent=read_json(opts.out/"best-plan.json");
