    auto contract=read_json(opts.out/"execution-contract.json");
    check(!contract.at("deployment_ready").get<bool>()&&!contract.at("native_execution_verified").get<bool>()&&contract.at("native_interfaces_required").size()==4,"execution contract concealed essential native interfaces");
    check(read_json(opts.out/"problem.json")==capped,"self-contained problem export differs from pinned input");
    auto bytecap=one();bytecap["max_checkpoint_bytes"]=1000;write_json(scratch/"bytecap.json",bytecap);
